    public function parse(\Phplrt\Contracts\Source\ReadableInterface $source): mixed
    {
        return $this->parser->parse($source);
    }

    private function reduceType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (\count($children) === 1) {
            return $children[0];
        }

        if ($this->features->conditions === false) {
            throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('conditional expressions', $offset);
        }

        $condition = match ($children[1]->id) {
            self::T_EQ => new Type\Condition\EqualConditionNode(
                $children[0],
                $children[2],
                $offset,
            ),
            self::T_NEQ => new Type\Condition\NotEqualConditionNode(
                $children[0],
                $children[2],
                $offset,
            ),
            default => throw Exception\InvalidConditionalOperatorException::becauseConditionalOperatorIsInvalid(
                $children[1]->value,
                $offset,
            ),
        };

        return new Type\TernaryExpressionNode(
            $condition,
            $children[3],
            $children[4],
            $offset,
        );
    }

    private function reduceUnionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (\count($children) === 1) {
            return $children[0];
        }

        if ($this->features->unions === false) {
            throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('union types', $offset);
        }

        $statement = new Type\UnionTypeNode($children);
        $statement->offset = $offset;

        return $statement;
    }

    private function reduceIntersectionType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if (\count($children) === 1) {
            return $children[0];
        }

        if ($this->features->intersections === false) {
            throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('intersection types', $offset);
        }

        $statement = new Type\IntersectionTypeNode($children);
        $statement->offset = $offset;

        return $statement;
    }

    private static function reduceNullableType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return new Type\NullableTypeNode($children[0], $offset);
    }

    private function reduceListOrOffsetType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        $statement = $children[0];
        $count = \count($children);

        for ($i = 1; $i < $count; ++$i) {
            $child = $children[$i];

            switch (true) {
                case $child === true:
                    if ($this->features->lists === false) {
                        throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('square bracket list types', $offset);
                    }

                    $statement = new Type\TypesListNode($statement, $offset);
                    break;
                case $child instanceof Type\TypeNode:
                    if ($this->features->offsets === false) {
                        throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('type offsets', $offset);
                    }

                    $statement = new Type\TypeOffsetAccessNode($statement, $child, $offset);
                    break;
                default:
                    throw Exception\InternalSemanticException::becauseSubNodeIsUnexpected(
                        \get_debug_type($child),
                        $offset,
                    );
            }
        }

        return $statement;
    }

    private static function reduceThisType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        return new Type\ThisNode($offset);
    }

    private function reduceLiteralType(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // The variables below are declared by the compiler
        $offset = $ctx->begin;

        if ($this->features->literals === false) {
            throw Exception\FeatureNotAllowedException::becauseFeatureIsNotAllowed('literal values', $offset);
        }
        return $children;
    }

